// Ежедневная сводка из review_queue.summary (истина — Stocker; контракт ASSET_STATE_CONTRACT).
// «Готово» — два разных понятия: metadata одобрена ≠ готово хотя бы для одной площадки.
const envelope = $input.first().json;
if (!envelope.ok) {
  throw new Error(`review.queue: ${JSON.stringify(envelope.error)}`);
}
const s = envelope.data.summary;
const LIMIT = 10;  // в сообщении — не больше 10 объектов; NOTIFY/SENT пишется только для показанных
const byState = Object.entries(s.by_state).filter(([, n]) => n > 0).map(([k, n]) => `${k}: ${n}`).join(', ');
const counts = Object.entries(s.problem_counts).map(([k, n]) => `${k}: ${n}`).join(', ');
const shown = s.problem_assets.slice(0, LIMIT);
const lines = [
  `Всего: ${s.total_assets}; состояния — ${byState || 'нет'}`,
  `Metadata одобрена: ${s.metadata_approved}; готово хотя бы для одной площадки: ${s.platform_ready}`,
  counts ? `Проблемы по кодам: ${counts}` : 'Проблемных объектов нет',
  ...(shown.length ? [`Требуют внимания (${shown.length} из ${s.problem_assets.length}):`,
                      ...shown.map(p => `#${p.id} ${p.filename} [${p.state}]: ${p.problems.join(', ')}`)] : []),
];
const attention = ['human_review', 'blocked', 'error', 'source_invalid'].some(k => s.by_state[k] > 0);
return [{ json: {
  severity: attention || s.problem_assets.length ? 'attention' : 'info',
  title: 'Stocker: ежедневная сводка',
  text: lines.join('\n'),
  data: { summary: s },
  kind: 'daily_digest',
  items: shown.map(p => ({ asset_id: p.id, key: new Date().toISOString().slice(0, 10) })),
} }];
